MODULE=''
MODULE_SHA='b4e4dd1ff9ecbe4037b5bdadc805c86191b6f541654f8ad03c6b395a851cc8ac'
CONFIG_SHA='abded1ea95a5208287e66ef4a4f6fc7f0591771a8a3e3bd80737e8b557df96a8'
import base64,gzip,hashlib,json,os,shutil,subprocess,sys,time,urllib.request
from pathlib import Path
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()=='89d53e38-4726-4c94-b958-53f2dfb3bd4e'
assert os.uname().release=='5.15.36-xilinx-v2022.2'
config=gzip.decompress(Path('/proc/config.gz').read_bytes()).decode()
values={line.split('=',1)[0]:line.split('=',1)[1] for line in config.splitlines() if line.startswith('CONFIG_') and not line.startswith('CONFIG_CC_VERSION_TEXT=')}
assert hashlib.sha256(json.dumps(values,sort_keys=True,separators=(',',':')).encode()).hexdigest()==CONFIG_SHA
name='aura_dp_retrain_candidate';state=Path('/sys/module')/name
assert not state.exists(),'Refuse taking ownership of an existing module'
assert shutil.which('insmod') and shutil.which('rmmod') and shutil.which('modetest')
source=Path(sys._getframe().f_code.co_filename).resolve();tag=hashlib.sha256(source.read_bytes()).hexdigest()[:16]
root=Path('/home/root/aura-display-sequence-20261024/module-diagnostic')/tag
root.mkdir(parents=True,exist_ok=False,mode=0o700)
raw=base64.b64decode(MODULE);assert hashlib.sha256(raw).hexdigest()==MODULE_SHA
module=root/'aura_dp_retrain_candidate.ko';module.write_bytes(raw)
assert b'vermagic=5.15.36-xilinx-v2022.2 SMP mod_unload aarch64' in raw
op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
def camera():
 with op.open('http://127.0.0.1:8790/health',timeout=4) as response:h=json.load(response)
 return {'pid':h['pid'],'frames':h['detected_frames'],'primary_overruns':h['dpu_schedule']['primary_period_overruns'],
 'optional_overruns':{k:v['overruns'] for k,v in h['dpu_schedule']['optional'].items()},'owner_fenced':h['dpu_schedule']['owner_fenced']}
def display():
 p=Path('/sys/class/drm/card0-DP-1');e=(p/'edid').read_bytes()
 return {**{k:(p/k).read_text().strip() for k in ['enabled','dpms','modes']},'edid_bytes':len(e),'edid_sha256':hashlib.sha256(e).hexdigest()}
report={'scope':'DIAGNOSTIC_ONLY_MODULE_LOAD_CAPTURE_AND_UNLOAD_NO_RETRAIN',
 'module_sha256':MODULE_SHA,'config_sha256':CONFIG_SHA,'enable_action':False,'trigger_writes':0,
 'display_control_commands':0,'models_created':0,'passed':False,'module_removed':False,'root':str(root)}
load=None;loaded=False
try:
 report['before_camera']=camera();report['before_display']=display()
 assert not report['before_camera']['owner_fenced'] and report['before_display']['enabled']=='enabled' and report['before_display']['dpms']=='On'
 load=subprocess.Popen(['insmod',str(module),'enable_action=0','capture_timeout_ms=5000'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
 # GETRESOURCES is read-only and may be issued while the module waits for its
 # public DRM argument. No -s/-w modesetting/property option is used.
 attempts=[]
 for i in range(12):
  if load.poll() is not None:break
  q=subprocess.run(['modetest','-M','xlnx','-c'],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,text=True,timeout=3)
  attempts.append({'exit_code':q.returncode,'stderr':q.stderr[-400:]})
  time.sleep(.1)
 out,error=load.communicate(timeout=15);report.update(load_exit=load.returncode,load_stderr=error[-1500:],readonly_query_attempts=attempts)
 assert load.returncode==0,'Module readiness did not initialize'
 loaded=True
 status=(state/'parameters/status').read_text().strip();report['module_status']=status
 fields=dict(item.split('=',1) for item in status.split())
 assert fields['ready']=='1' and fields['enable_action']=='0' and fields['triggered']=='0' and fields['action_returned']=='0'
 report['diagnostic_capture_passed']=True
except BaseException as exc:report['failure']=type(exc).__name__+': '+str(exc)
finally:
 if loaded and load.poll()==0:
  remove=subprocess.run(['rmmod',name],capture_output=True,text=True,timeout=10)
  report['unload_exit']=remove.returncode;report['unload_stderr']=remove.stderr[-700:]
 report['module_removed']=not state.exists()
 report['after_camera']=camera();report['after_display']=display()
 before=report.get('before_camera',{});after=report['after_camera']
 report['same_camera_pid']=before.get('pid')==after['pid']
 report['new_optional_overruns']={k:after['optional_overruns'][k]-before.get('optional_overruns',{}).get(k,after['optional_overruns'][k]) for k in after['optional_overruns']}
 report['cached_display_unchanged']=report.get('before_display')==report['after_display']
 report['passed']=bool(report.get('diagnostic_capture_passed') and report['module_removed'] and report['same_camera_pid']
  and not after['owner_fenced'] and not any(report['new_optional_overruns'].values()) and report['cached_display_unchanged'])
 (root/'report.json').write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps(report))
